// src/lib/mcp/tools/detalhar-cotacao.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z4 } from "npm:zod@^3.25.76";
var detalhar_cotacao_default = defineTool4({
  name: "detalhar_cotacao",
  title: "Detalhar cota\xE7\xE3o",
  description: "Retorna os itens de uma cota\xE7\xE3o com quantidades, embalagem e os pre\xE7os recebidos de cada fornecedor, incluindo o menor pre\xE7o por item.",
  inputSchema: {
    cotacao_id: z4.string().uuid().describe("ID da cota\xE7\xE3o (use listar_cotacoes para obter).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ cotacao_id }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado." }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const { data: cotacao, error: cotacaoError } = await supabase.from("cotacoes").select("id, nome, status, loja_id, prazo_resposta, created_at").eq("id", cotacao_id).maybeSingle();
    if (cotacaoError) return { content: [{ type: "text", text: cotacaoError.message }], isError: true };
    if (!cotacao) {
      return { content: [{ type: "text", text: "Cota\xE7\xE3o n\xE3o encontrada." }], isError: true };
    }
    const [{ data: itens, error: itensError }, { data: fornecedores }] = await Promise.all([
      supabase.from("cotacao_produtos").select("id, nome, ean, quantidade, tipo_embalagem, fator_embalagem, precos(preco, fornecedor_id)").eq("cotacao_id", cotacao_id).order("nome", { ascending: true }),
      supabase.from("fornecedores").select("id, nome")
    ]);
    if (itensError) return { content: [{ type: "text", text: itensError.message }], isError: true };
    const nomeFornecedor = new Map((fornecedores ?? []).map((f) => [f.id, f.nome]));
    const resultado = (itens ?? []).map((item) => {
      const precos = (item.precos ?? []).filter((p) => typeof p.preco === "number").map((p) => ({
        fornecedor_id: p.fornecedor_id,
        fornecedor: p.fornecedor_id ? nomeFornecedor.get(p.fornecedor_id) ?? null : null,
        preco: p.preco
      })).sort((a, b) => a.preco - b.preco);
      return {
        id: item.id,
        nome: item.nome,
        ean: item.ean,
        quantidade: item.quantidade,
        embalagem: item.tipo_embalagem,
        fator_embalagem: item.fator_embalagem,
        precos,
        melhor_preco: precos[0] ?? null
      };
    });
    const payload = { cotacao, total_itens: resultado.length, itens: resultado };
    return {
      content: [{ type: "text", text: JSON.stringify(payload) }],
      structuredContent: payload
    };
  }
});

