import { defineTool as defineTool7 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z7 } from "npm:zod@^3.25.76";
var buscar_catalogo_default = defineTool7({
  name: "buscar_catalogo",
  title: "Buscar no cat\xE1logo",
  description: "Busca produtos no cat\xE1logo mestre do Compra360 por nome ou por c\xF3digo de barras (EAN).",
  inputSchema: {
    termo: z7.string().trim().min(2).describe("Nome do produto ou EAN (s\xF3 d\xEDgitos)."),
    limite: z7.number().int().min(1).max(50).default(20).describe("M\xE1ximo de resultados.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ termo, limite }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado." }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const isEan = /^\d+$/.test(termo);
    let query = supabase.from("catalogo_mestre").select("id, nome, ean, categoria, embalagem, fator_embalagem").eq("ativo", true).limit(limite ?? 20);
    query = isEan ? query.or(`ean.ilike.${termo}%,nome.ilike.%${termo}%`) : query.ilike("nome", `%${termo}%`);
    const { data, error } = await query;
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? []) }],
      structuredContent: { produtos: data ?? [] }
    };
  }
});

